package httpserver
import("context";"encoding/json";"net/http";"time")
func(a AdminHandler)Audit(w http.ResponseWriter,r *http.Request){if !a.authorized(r){writeJSON(w,401,map[string]string{"error":"unauthorized"});return};ctx,cancel:=context.WithTimeout(r.Context(),3*time.Second);defer cancel();rows,err:=a.DB.QueryContext(ctx,`SELECT id,actor,action,resource_type,resource_id,metadata,created_at FROM admin_audit_log ORDER BY created_at DESC LIMIT 100`);if err!=nil{writeJSON(w,500,map[string]string{"error":"internal_error"});return};defer rows.Close();items:=[]map[string]any{};for rows.Next(){var id int64;var actor,action,typ string;var rid *string;var raw []byte;var created time.Time;if rows.Scan(&id,&actor,&action,&typ,&rid,&raw,&created)==nil{var meta any;_ = json.Unmarshal(raw,&meta);items=append(items,map[string]any{"id":id,"actor":actor,"action":action,"resource_type":typ,"resource_id":rid,"metadata":meta,"created_at":created})}};writeJSON(w,200,map[string]any{"data":items})}
